# update API key functionality
def pricing_cmcmod__update_api_key(apikey):
   
   if apikey == "" or apikey == None:
      d.pricing_cmcmod__headers = {
         'Accepts': 'application/json',
      }
   else:
      d.pricing_cmcmod__headers = {
         'Accepts': 'application/json',
         'X-CMC_PRO_API_KEY': apikey,
      }
   
   c.pricing_cmcmod__apikey = apikey
   
   pricing_storage__pricing_mod_upt_req_params(d.pricing_cmcmod__headers)


# main functionality to get price from remote cmc source
def pricing_cmcmod__get_price(req):
   
   # first try by ID because is exact
   price = pricing_cmcmod__get_price_by_id(req)
   
   # then it try to get price by name
   if price == 0:
      price = pricing_cmcmod__get_price_by_slug(req)
      
   return price

# get price by cmc id also named as UCID
def pricing_cmcmod__get_price_by_id(req):
   
   maker_name = req.get('maker_name', None)
   taker_name = req.get('taker_name', None)
   maker_ticker = req.get('maker_ticker', None)
   taker_ticker = req.get('taker_ticker', None)
   maker_ucid = req.get('maker_ucid', None)
   taker_ucid = req.get('taker_ucid', None)
   
   pro_key = req.get('X-CMC_PRO_API_KEY', None)
   
   price = 0
   
   if maker_ucid == "" or maker_ucid == None or taker_ucid == "" or taker_ucid == None:
         LOG_ERROR(f"Request {req} is invalid")
         return price
   
   # prepare parameters for the API request
   parameters = {
     'amount': 1,
     'id': maker_ucid,
     'convert_id': taker_ucid
   }
   
   response = None
   
   if pro_key != None:
      pro_headers = {
         'Accept': 'application/json',
         'X-CMC_PRO_API_KEY': pro_key,
      }
      response = requests.get(c.pricing_cmcmod__url_byid, headers=pro_headers, params=parameters)
   
   if response == None or response.status_code != 200:
      response = requests.get(c.pricing_cmcmod__url_byid, headers=d.pricing_cmcmod__headers, params=parameters)

   # Check if the request was successful
   if response.status_code == 200:
      data = response.json()
      
      LOG_DEBUG(data)
      
      price = data['data']['quote'][taker_ucid]['price']
      
      LOG_DEBUG(f"{maker_name}/{taker_name} {maker_ticker}/{taker_ticker} {maker_ucid}/{taker_ucid} price {price}")
   else:
      LOG_ERROR(f"{maker_name}/{taker_name} {maker_ticker}/{taker_ticker} {maker_ucid}/{taker_ucid} - {response.status_code} - {response.text}")
   
   return price


# get price by cmc base currency name also named slug-name
def pricing_cmcmod__get_price_by_slug(req):
   
   maker_name = req.get('maker_name', None)
   taker_name = req.get('taker_name', None)
   maker_ticker = req.get('maker_ticker', None)
   taker_ticker = req.get('taker_ticker', None)
   maker_ucid = req.get('maker_ucid', None)
   taker_ucid = req.get('taker_ucid', None)
   
   pro_key = req.get('X-CMC_PRO_API_KEY', None)
   
   price = 0
   
   if maker_name == "" or maker_name == None or taker_name == "" or taker_name == None:
         LOG_ERROR(f"Request {req} is invalid")
         return price
   
   # prepare parameters for the API request
   parameters = {
      "slug": f"{maker_name},{taker_name}",
      "convert": "USD"
   }
   
   response = None
   
   if pro_key != None:
      pro_headers = {
         'Accept': 'application/json',
         'X-CMC_PRO_API_KEY': pro_key,
      }
      response = requests.get(c.pricing_cmcmod__url_byslug, headers=pro_headers, params=parameters)
   
   if response == None or response.status_code != 200:
      response = requests.get(c.pricing_cmcmod__url_byslug, headers=d.pricing_cmcmod__headers, params=parameters)

   # Check if the request was successful
   if response.status_code == 200:
      data = response.json()
      
      LOG_DEBUG(data)
      
      maker_price_usd = data['data'][0]["quotes"][0]["price"]
      taker_price_usd = data['data'][1]["quotes"][0]["price"]
      
      price = maker_price_usd / taker_price_usd
      
      pair = pricing_storage__get_pair_id(maker_ticker, "USD", "cmc")
      pricing_storage__set_price(pair, maker_price_usd)
      
      pair = pricing_storage__get_pair_id(taker_ticker, "USD", "cmc")
      pricing_storage__set_price(pair, taker_price_usd)
      
      LOG_DEBUG(f"{maker_name}/{taker_name} {maker_ticker}/{taker_ticker} {maker_ucid}/{taker_ucid} price {price}")
   else:
      LOG_ERROR(f"{maker_name}/{taker_name} {maker_ticker}/{taker_ticker} {maker_ucid}/{taker_ucid} - {response.status_code} - {response.text}")
   
   return price


# command line interface - cmc api key update commands
def pricing_cmcmod__cli_apikey_cmd(cmd1, arg2, arg3):
   global c, s, d
   
   LOG_DEBUG("CLI command >> {} {} {}".format(cmd1, arg2, arg3))
   
   # default action is to cancel all orders on configured address
   if arg2 == "apikey" and len(arg3) >= 0: 
      pricing_cmcmod__update_api_key(arg3)
   else:
      LOG_ERROR("exit arguments >> {} >> {} >> are invalid".format(arg2, arg3))
   
   return


